function isReviewAction(
  value: unknown
): value is ReviewAction {
  return (
    value ===
      "approve" ||
    value ===
      "reject"
  );
}

export async function POST(
  request: Request
) {
  try {
    const accessToken =
      getBearerToken(
        request
      );

    if (!accessToken) {
      return Response.json(
        {
          error:
            "Authentication required.",
        },
        {
          status: 401,
        }
      );
    }

    const supabase =
      createAuthenticatedSupabase(
        accessToken
      );

    const {
      data: userData,
      error: userError,
    } =
      await supabase.auth.getUser(
        accessToken
      );

    if (
      userError ||
      !userData.user
    ) {
      return Response.json(
        {
          error:
            "Authentication required.",
        },
        {
          status: 401,
        }
      );
    }

    const body =
      await request.json();

    const candidateId =
      typeof body?.candidateId ===
        "string"
        ? body.candidateId.trim()
        : "";

    const action =
      body?.action;

    if (
      !candidateId ||
      !isReviewAction(
        action
      )
    ) {
      return Response.json(
        {
          error:
            "candidateId and valid action are required.",
        },
        {
          status: 400,
        }
      );
    }

    const {
      data,
      error,
    } =
